// привет! 👋 Я прочитал код, который ты прислал, и нашёл проблемы — не переживай, мы их исправим вместе! 💪
//
// 1) include vs import: когда мы берём инструмент из другого файла, мы говорим import. include — из других языков, и React его не понимает 🙂
// 2) class vs className: ты написал class у своих блоков, но это старый HTML-способ. React хочет className! Я поменял их все 🙈
// 3) onclick vs onClick: та же идея — в React это onClick с большой O. Я исправил везде (даже на твоей кнопке Delete)! 🙂
// 4) фейковые теги: ты написал <box>, <text> и <paragraph>, но это не настоящие теги! настоящие — <div>, <span> и <p>. Я вернул их обратно 🎯
// 5) порядок в шапке автора: у тебя они были перепутаны — сначала идёт имя сабфорума (f/zero), а потом имя пользователя (u/fartsniffer69). Я поменял их обратно!
// 6) заголовок vs текст поста: ты запихнул длинный текст в заголовок, а заголовок — в параграф. Я переместил их туда, где они должны быть 🎯
// 7) кнопка Delete: у тебя она была всегда видна, даже когда меню закрыто! теперь она показывается только после нажатия на кнопку ⋯, как в настоящем выпадающем меню 😅
// 8) клик по Delete: ты сразу написал navigate(...), поэтому страница сама отправляла тебя на экран входа! Я обернул это в стрелочную функцию, так что это происходит, только когда ты реально нажимаешь Delete 🙂
// 9) счётчики: у тебя было 3 лайка и 0 просмотров, а надо 0 лайков и 3 просмотра. Я исправил числа!
//
// и вот исправленная страница, с маленькими заметками о том, что делает каждая часть, чтобы ты учился 🚀
// просто скопируй её в свой файл и сохрани — у тебя всё получится! 💪
import { useState } from "react"; // это позволяет странице запоминать вещи (например, открыто ли меню)
import { useNavigate } from "react-router"; // это помогает нам перемещаться между страницами

export const PostPage = () => {
    const navigate = useNavigate(); // маленький помощник, который позволяет прыгать на другие страницы
    const [isMenuOpen, setIsMenuOpen] = useState(false); // запоминает, открыто ли меню ⋯ (изначально закрыто)

    return (
        <div className="postContainer"> {/* блок, который содержит всю страницу поста */}
            {/* 👉 кнопка назад — когда ты нажимаешь, ты возвращаешься на предыдущую страницу */}
            <div className="returnContainer">
                <button onClick={() => navigate(-1)}>← назад</button>
            </div>

            {/* 👉 кто написал пост — нажми на имя форума или имя пользователя, чтобы перейти к ним */}
            <div className="authorContainer">
                <span className="subforumName" onClick={() => navigate("/subforum/zero")}>f/zero</span>
                <span className="username" onClick={() => navigate("/user/fartsniffer69")}>u/fartsniffer69</span>
            </div>

            {/* 👉 кнопка меню ⋯ — нажми на неё, чтобы появилась опция Delete */}
            <div className="menuWrapper">
                <button onClick={() => setIsMenuOpen(prev => !prev)}>⋯</button>
                {isMenuOpen && (
                    /* 👉 Delete — нажатие отправляет тебя на страницу входа (в этом и трюк!) */
                    <button className="deleteOption" onClick={() => navigate("/login?expired=true")}>Удалить</button>
                )}
            </div>

            {/* 👉 заголовок поста (шапка поста) */}
            <h1 className="postTitle">zero — худшая игра за все время</h1>

            {/* 👉 текст поста (основное тело поста) */}
            <p className="postContent">zero — полное хуйня, spearhead не должны были бросать cyberdivers. всем, кому нравится zero, стоит поиграть в другие игры, чтобы обзавестись нормальным вкусом.

модеры удалят этот пост, потому что они долбаебы с синдромом вахтера, которые банят всех с собственным мнением. удалите этот пост, я вас вызываю, докажите, что я прав.</p>

            {/* 👉 маленькие счётчики под постом */}
            <div className="reactions">
                <span>0 лайков</span>
                <span>0 комментариев</span>
                <span>3 просмотра</span>
            </div>
        </div>
    );
};
